local KTool = CS.Engine.Lib.KTool
---@class OverseaManageCafeCattyRankingsCell
local OverseaManageCafeCattyRankingsCell = Class('OverseaManageCafeCattyRankingsCell')
local CommonPlayerHeadNode = "Game.Behaviours.CommonPlayerHeadNode"
local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
local CommonGoodsList = "Game.Behaviours.CommonGoodsList"
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
local ShowGoodsId = {
    [1] = Constants.Currency.TipCoin,
    [2] = 0,
    [3] = Constants.Currency.CartCatTicket,
}


function OverseaManageCafeCattyRankingsCell:__init()
    self._data = nil
    self._commonPlayerHeadNodeScr = nil
end

function OverseaManageCafeCattyRankingsCell:__delete()
    self._data = nil
    self.rankType = nil
    self._commonPlayerHeadNodeScr = nil
end

function OverseaManageCafeCattyRankingsCell:Awake()
    if not self._commonPlayerHeadNodeScr then
        self._commonPlayerHeadNodeScr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, CommonPlayerHeadNode)
    end
    SetButtonAction(self.BtnDetails, Bind(self, self.OnBtnDetailInfo))
    SetButtonAction(self.BtnIcon,Bind(self,self.OnBtnIconClick))
end

function OverseaManageCafeCattyRankingsCell:RefreshShow(data,isMe,rankType)
    if not data then
        return
    end
    self._data = data
    self._isMe = isMe
    self.rankType = rankType or MaidCoffeeConstants.CoffeeRankType.CafeTipRank

    if not isMe then
        self:FillOtherInfo()
    end
    local goodsId = ShowGoodsId[rankType]
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    if goodsVo then
        CfUtils.FillImage(self.ImgIcon,goodsVo.photoPath)
    end
end

--绘制别人的
function OverseaManageCafeCattyRankingsCell:FillOtherInfo()
    self:FillCommonInfo()
    self:FillRankReward()
end

function OverseaManageCafeCattyRankingsCell:RefreshSelfShow(myRank,myScore,allNum,rankType)
    self._isMe = true
    self.rankType = rankType or MaidCoffeeConstants.CoffeeRankType.CafeTipRank
    local playerDojo = comp:GetPlayerDojo()
    self._data = {
        rank = myRank,
        score = myScore,
        playerId = playerDojo.playerId,
        avatar = playerDojo.playerAvatar,
        avatarFrame = playerDojo.playerAvatarFrame,
        name = playerDojo.playerName,
        level = playerDojo.level,
    }

    self.allNum = allNum
    local isInRank = self._data.score > 0
    self:FillCommonInfo()
    if isInRank then
        KTool.SetActive(self.TxtNo.gameObject,false)
        KTool.SetActive(self.ItileRank.gameObject,true)
        local isPercent = self:IsInPercentRank()
        KTool.SetActive(self.NotEnterNode.gameObject,isPercent)
        KTool.SetActive(self.ImgRank.gameObject,not isPercent)
        KTool.SetActive(self.Txtranking.gameObject,not isPercent)
        if isPercent then
            local percent = math.ceil((self._data.rank/self.allNum) * 100)
            CfUtils.SetActive(self.NotEnterNode.transform:Find("TxtRanking3"), percent > 80)
            if percent > 80 then
                CfUtils.FillText(self.NotEnterNode.transform:Find("TxtRanking2"), "80%")
            else
                CfUtils.FillText(self.NotEnterNode.transform:Find("TxtRanking2"), percent.."%")
            end
        else
            KTool.SetActive(self.NotEnterNode.gameObject,false)
            KTool.SetActive(self.ImgRank.gameObject,true)
            KTool.SetActive(self.Txtranking.gameObject,true)
        end
        self:FillRankReward(isPercent)
    else
        KTool.SetActive(self.TxtNo.gameObject,true)
        KTool.SetActive(self.ItileRank.gameObject,false)
        self:FillRankReward()
    end

    local goodsId = ShowGoodsId[rankType]
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    if goodsVo then
        CfUtils.FillImage(self.ImgIcon,goodsVo.photoPath)
    end
end

function OverseaManageCafeCattyRankingsCell:IsInPercentRank()
    local vos = self:GetRankVos()
    for k, v in pairs(vos) do
        if v.type == 1 then
            if checkNumber(v.upperLimit) <= self._data.rank and checkNumber(v.lowerLimit) >= self._data.rank then
                return false
            end
        end
    end
    return true
end

--通用的
function OverseaManageCafeCattyRankingsCell:FillCommonInfo()
    CfUtils.FillText(self.TxtDamage, checkNumber(self._data.score))
    CfUtils.FillText(self.Txtranking, checkNumber(self._data.rank))
    CfUtils.FillText(self.TextLevel, "Lv."..checkNumber(self._data.level))
    local status = checkNumber(self._data.rank) > 4 and 5 or checkNumber(self._data.rank)
    CfUtils.SetUISwitchText(self.Txtranking, status)
    CfUtils.SetUISwitchImage(self.ImgRank, status)
    CfUtils.SetUISwitchImage(self.ImgRank2, status)
    --CfUtils.FillImage(self.Imgbg, CfUtils.GetRankListBg(checkNumber(self._data.rank)), false)
    local playerDojo = comp:GetPlayerDojo()
    if self._commonPlayerHeadNodeScr then
        self._commonPlayerHeadNodeScr:FreshAvatarFrame(self._data.avatar, self._data.avatarFrame)
        self._commonPlayerHeadNodeScr:SetCallBack(function()
            if (checkNumber(self._data.playerId) == checkNumber(playerDojo.playerId)) then
                return 
            end
            Events.Broadcast("MaidCoffee_VimCraStageChange",false)

            -- 直接进入 他人的 个人信息界面2D版 
            GameUtils.ShowPlayerInfo( self._data.playerId,  
                {{ id = Constants.UITypeIds.UIMaidCoffeeManagerDialog},
                { id = Constants.UITypeIds.UIMaidCoffeeCattyMain},
                { id = Constants.UITypeIds.TakeoutVipOrderDialog},
                { id = Constants.UITypeIds.UIMaidCoffeeCattyRank},}
            )   
            -- 下方为旧方案, 暂被替代:
            -- GameUtils.ShowCommonPlayerHeadOption(self._commonPlayerHeadNodeScr.controller.gameObject, Constants.PlayerHeadOptionType.Common,{
            --     playerId    = self._data.playerId,
            --     name        = self._data.name,
            --     level       = self._data.level,
            --     avatar      = self._data.avatar,
            --     avatarFrame = self._data.avatarFrame,
            --     exclude = {{ id = Constants.UITypeIds.UIMaidCoffeeManagerDialog},
            --                { id = Constants.UITypeIds.UIMaidCoffeeCattyMain},
            --                { id = Constants.UITypeIds.TakeoutVipOrderDialog},
            --                { id = Constants.UITypeIds.UIMaidCoffeeCattyRank},}
            -- })  
        end)
    end
    CfUtils.FillText(self.TxtName, self._data.name)

    if self.ImgMyself then
        KTool.SetActive(self.ImgMyself, (checkNumber(self._data.playerId) == checkNumber(playerDojo.playerId)))
    end
    KTool.SetActive(self.BtnDetails, (checkNumber(self._data.playerId) ~= checkNumber(playerDojo.playerId)))
end

--奖励
function OverseaManageCafeCattyRankingsCell:FillRankReward(isPercent)
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsList)
    if scr then
        local t = {}
        if self._isMe then
            if self._data.score > 0 then
                if isPercent then
                    local vo = self:GetPercentRewardVo()
                    if vo then
                        t = vo.rewards
                    end
                else
                    t = self:GetRankRewardByRankNum(checkNumber(self._data.rank))
                end
            end
        else
            t = self:GetRankRewardByRankNum(checkNumber(self._data.rank))
        end
        local isHaveReward = true

        if not t or table.count(t) <= 0 then
            isHaveReward = false
        end
        KTool.SetActive(self.CommonGoodsList, isHaveReward)
        KTool.SetActive(self.TextNoReward, not isHaveReward)

        if isHaveReward then
            scr:FreshBaseUI(t, false)
        end
    end
end

function OverseaManageCafeCattyRankingsCell:GetRankRewardByRankNum(rankNum)
    local vos = self:GetRankVos()
    for k, v in pairs(vos) do
        if v.type == 1 then
            if checkNumber(v.upperLimit) <= rankNum and checkNumber(v.lowerLimit) >= rankNum then
                return v.rewards
            end
        end
    end
    return {}
end

function OverseaManageCafeCattyRankingsCell:GetPercentRewardVo()
    local percent = math.ceil((self._data.rank/self.allNum) * 100)  --math.floor(self._data.rank/self.allNum) * 100
    local vos = self:GetRankVos()
    for k, v in pairs(vos) do
        if v.type == 2 then
            if checkNumber(v.upperLimit) <= percent and checkNumber(v.lowerLimit) >= percent then
                return v
            end
        end
    end
    return nil
end

function OverseaManageCafeCattyRankingsCell:GetRankVos()
    local vos
    if self.rankType == MaidCoffeeConstants.CoffeeRankType.CafeTipRank then
        vos = CfUtils.GetCf(AutoIds.IdSetting4041, "MaidCoffeeCattyRankVo", true)
    elseif self.rankType == MaidCoffeeConstants.CoffeeRankType.VipOrderRank then
        vos = CfUtils.GetCf(AutoIds.IdSetting3057, "MaidCoffeeCattyRankVo", true)
    end
    return vos
end

function OverseaManageCafeCattyRankingsCell:OnBtnDetailInfo()
    SceneManagement:GetInstance():SetActive(Constants.IdSceneSetting46,false,true)
    Events.Broadcast("MaidCoffee_VimCraStageChange",false)
    GameUtils.ShowPlayerInfo(self._data.playerId, {
        { id = Constants.UITypeIds.UIMaidCoffeeManagerDialog},
        { id = Constants.UITypeIds.UIMaidCoffeeCattyMain},
        { id = Constants.UITypeIds.TakeoutVipOrderDialog},
        { id = Constants.UITypeIds.UIMaidCoffeeCattyRank},
    })
end

function OverseaManageCafeCattyRankingsCell:OnBtnIconClick()
    local goodsId = ShowGoodsId[self.rankType]
    if goodsId then
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        if goodsVo then
            GameUtils.ShowCommonTipsBoard(self.BtnIcon.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
        end
    end
end

