    CfUtils.PlayDelayShowAnimation(self.AniRoot, delayIndex, 'UI_Common_List_Cell_Show')
end

function OverseaManageCafeCattyRankingsCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
